import { Component, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmCardImports } from '@spartan-ng/helm/card';
import type { Hero } from '../../domain/hero';
import { PowerMeter } from '../power-meter/power-meter';

/** Two-letter avatar fallback taken from the hero's name: "Dr. Ion" becomes "DR". */
function initialsOf(name: string): string {
  return name.replace(/[^A-Za-z]/g, '').slice(0, 2).toUpperCase();
}

/** A hero summary card. Presentational: takes a hero as input and injects nothing but the router link. */
@Component({
  selector: 'app-hero-card',
  imports: [HlmCardImports, HlmAvatarImports, HlmBadgeImports, PowerMeter, RouterLink],
  template: `
    <hlm-card>
      <hlm-card-header>
        <h3 hlmCardTitle>
          <a class="underline-offset-4 hover:underline" [routerLink]="['/detail', hero().id]">{{ hero().name }}</a>
        </h3>
        <p hlmCardDescription>{{ hero().alias }} · {{ hero().id }}</p>
      </hlm-card-header>

      <div hlmCardContent class="flex flex-col gap-4">
        <div class="flex flex-wrap items-center gap-3">
          <hlm-avatar size="lg" aria-hidden="true">
            <span hlmAvatarFallback>{{ initials() }}</span>
          </hlm-avatar>
          <div class="flex flex-wrap gap-1">
            <span hlmBadge variant="secondary">{{ hero().powerClass }}</span>
            <span hlmBadge variant="outline">{{ hero().status }}</span>
          </div>
        </div>

        <app-power-meter [value]="hero().powerIndex" [label]="'Power index for ' + hero().name" />

        <p class="text-xs text-muted-foreground">
          {{ hero().clearance }} · {{ hero().missionCount }} missions · {{ hero().successRate }}% success
        </p>
      </div>
    </hlm-card>
  `,
})
export class HeroCard {
  readonly hero = input.required<Hero>();

  protected initials(): string {
    return initialsOf(this.hero().name);
  }
}
=== src/app/forms/form-field-meta.ts
/**
 * Presentation metadata that rides on a zod field via `.meta()`. Strongly typed,
 * so a missing label is a compile error rather than a runtime surprise. A form
 * component reads this off the schema instead of restating labels and control
 * kinds in a parallel config object.
 */
export type ControlKind = 'text' | 'email' | 'number' | 'select' | 'checkbox' | 'switch' | 'textarea';

export interface FormFieldMeta {
  label: string;
  control: ControlKind;
  placeholder?: string;
  options?: ReadonlyArray<{ value: string; label: string }>;
  order?: number;
  help?: string;
}
=== src/app/forms/zod-meta.ts
import type { z } from 'zod';
import type { FormFieldMeta } from './form-field-meta';

/**
 * Read the FormFieldMeta off each field of a zod object schema. Keeps the label,
 * control kind, and placeholder on the schema (one source of truth) so a form
 * component reads them instead of restating them. Pair with `validateStandardSchema`
 * from `@angular/forms/signals` for validation, so shape, rules, and labels all
 * live on the one schema.
 */
export function formMeta(schema: z.ZodObject<z.ZodRawShape>): Record<string, FormFieldMeta> {
  const meta: Record<string, FormFieldMeta> = {};
  for (const [name, field] of Object.entries(schema.shape)) {
    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
  }
  return meta;
}
